function elevationLedger(benchmarks, statements) {
  const links = Array.from({ length: benchmarks }, () => []);
  const results = [];
  for (const [a, b, d] of statements) {
    const heightFromA = new Map([[a, 0]]);
    const stack = [a];
    while (stack.length > 0) {
      const at = stack.pop();
      for (const [other, delta] of links[at]) {
        if (!heightFromA.has(other)) {
          heightFromA.set(other, heightFromA.get(at) + delta);
          stack.push(other);
        }
      }
    }
    if (!heightFromA.has(b)) {
      links[a].push([b, -d]);
      links[b].push([a, d]);
      results.push("new");
    } else {
      results.push(heightFromA.get(b) === -d ? "known" : "conflict");
    }
  }
  return results;
}

function elevationLedger(benchmarks, statements) {
  const parent = Array.from({ length: benchmarks }, (_, i) => i);
  const size = new Array(benchmarks).fill(1);
  const offset = new Array(benchmarks).fill(0);
  let rise = 0;
  const find = (x) => {
    const path = [];
    let root = x;
    while (parent[root] !== root) {
      path.push(root);
      root = parent[root];
    }
    let total = 0;
    for (let i = path.length - 1; i >= 0; i--) {
      total += offset[path[i]];
      offset[path[i]] = total;
      parent[path[i]] = root;
    }
    rise = x === root ? 0 : offset[x];
    return root;
  };
  const results = [];
  for (const [a, b, d] of statements) {
    const rootA = find(a);
    const riseA = rise;
    const rootB = find(b);
    const riseB = rise;
    if (rootA === rootB) {
      results.push(riseA - riseB === d ? "known" : "conflict");
      continue;
    }
    const rootGap = d - riseA + riseB;
    if (size[rootA] <= size[rootB]) {
      parent[rootA] = rootB;
      offset[rootA] = rootGap;
      size[rootB] += size[rootA];
    } else {
      parent[rootB] = rootA;
      offset[rootB] = -rootGap;
      size[rootA] += size[rootB];
    }
    results.push("new");
  }
  return results;
}
